From 4d89eaa93466fc78122e04866a40535cf22d3247 Mon Sep 17 00:00:00 2001
From: Roman Lebedev <lebedev.ri@gmail.com>
Date: Thu, 14 Sep 2017 16:01:10 +0300
Subject: [PATCH] PefDecoder::decodeRawInternal(): don't catch IOException.

---
 src/librawspeed/decoders/PefDecoder.cpp | 12 ++++--------
 1 file changed, 4 insertions(+), 8 deletions(-)

diff --git a/src/librawspeed/decoders/PefDecoder.cpp b/src/librawspeed/decoders/PefDecoder.cpp
index b772abd..2c8b307 100644
--- a/src/librawspeed/decoders/PefDecoder.cpp
+++ b/src/librawspeed/decoders/PefDecoder.cpp
@@ -79,14 +79,10 @@ RawImage PefDecoder::decodeRawInternal() {
     ThrowRDE("Unexpected image dimensions found: (%u; %u)", width, height);

   mRaw->dim = iPoint2D(width, height);
-  try {
-    PentaxDecompressor p(mRaw, getRootIFD());
-    mRaw->createData();
-    p.decompress(bs);
-  } catch (IOException &e) {
-    mRaw->setError(e.what());
-    // Let's ignore it, it may have delivered somewhat useful data.
-  }
+
+  PentaxDecompressor p(mRaw, getRootIFD());
+  mRaw->createData();
+  p.decompress(bs);

   return mRaw;
 }
